random = {}
random.used = {}
function random.get(Length)
    -- Valid Lua identifiers only (not full ASCII — that breaks load)
    -- Full 0-255 used later in bytecode name scramble (getRandom)
    Length = Length or 8
    local first = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"
    local rest  = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"
    local Table = {}
    local fi = math.random(1, #first)
    Table[1] = first:sub(fi, fi)
    for index = 2, Length do
        local ri = math.random(1, #rest)
        Table[index] = rest:sub(ri, ri)
    end
    local Content = table.concat(Table)
    if random.used[Content] then
        return random.get(Length + 1)
    end
    random.used[Content] = 1
    if DATA and string.match(DATA, '[^%w_]' .. Content .. '[^%w_]') then
        return random.get(Length + 1)
    end
    return Content
end
local function hidegg(stro)
    local strs, name = stro
    local f={}
    for v in strs:gmatch("[^%w_.](gg%.[%w_]+)") do
        f[v]=v:gsub("([%%.])", "%%%1")
    end
    local o={}
    for k, v in pairs (f) do
        name = random.get()
        strs=strs:gsub('([^%w_.])('..v..')([^%w_])', function (a,b,c)
            o[v]= name .."="..b
            return a..name..c
        end)
    end
    local y = ""
    for k, v in pairs(o) do
        y=y..v.." "
    end
    local strs=y..strs
    return load(strs) and strs or stro
end
