-- (1) Manifest string encrypt (iga-style)
if g.opt.manifest then do
  local src = DATA
  local used = {}
  local function rnd(n)
    n = n or 6
    local t = {}
    for i = 1, n do
      local r = math.random(1, 26)
      t[i] = string.char((i % 2 == 1) and (r + 96) or (r + 64))
    end
    local c = table.concat(t)
    if used[c] or (src and src:match('[^%w_]'..c..'[^%w_]')) then return rnd(n+1) end
    used[c] = true
    random.used[c] = 1
    return c
  end
  local an, sn, dn = rnd(7), rnd(7), rnd(7)
  local au, su = {}, {}
  local ad = { an.."={}" }
  local sd = { sn.."={}" }
  local dec = dn..'=function(T)local d="" for _,v in pairs(T)do d=d..'..an..'[v] end return d end'
  local function is_url(body)
    local b = body:lower()
    return b:find("http://",1,true) or b:find("https://",1,true)
  end
  local function enc_one(q)
    local body = q:sub(2,-2)
    if body == "" then return q end
    local plain = body:gsub("\\n","\n"):gsub("\\r","\r"):gsub("\\t","\t"):gsub('\\"','"'):gsub("\\\\","\\")
    if is_url(plain) then return q end
    for i=1,#plain do if plain:byte(i)>255 then return q end end
    if su[plain] then return "("..sn.."["..su[plain].."])" end
    local keys = {}
    for i=1,#plain do
      local b = plain:byte(i)
      local key = au[b]
      if not key then
        key = '"'..rnd(6)..'"'
        au[b] = key
        ad[#ad+1] = an.."["..key.."]=string.char("..b..")"
      end
      keys[#keys+1] = key
    end
    local idx = '"'..rnd(6)..'"'
    su[plain] = idx
    sd[#sd+1] = sn.."["..idx.."]="..dn.."({"..table.concat(keys,",").."})"
    return "("..sn.."["..idx.."])"
  end
  local res, i, n = {}, 1, #src
  while i <= n do
    local c = src:sub(i,i)
    if c == '"' or c == "'" then
      local j, esc, ok = i+1, false, true
      while j <= n do
        local ch = src:sub(j,j)
        if esc then esc = false
        elseif ch == "\\" then esc = true
        elseif ch == c then break
        elseif ch == "\n" then ok = false break end
        j = j + 1
      end
      if ok and j <= n then
        res[#res+1] = enc_one(src:sub(i,j))
        i = j + 1
      else
        res[#res+1] = c
        i = i + 1
      end
    else
      res[#res+1] = c
      i = i + 1
    end
  end
  local mixed = table.concat(ad,"\n").."\n"..dec.."\n"..table.concat(sd,"\n").."\n"..table.concat(res)
  if load(mixed) then DATA = mixed; gg.toast("Kinzi Manifest OK")
  else gg.toast("Kinzi Manifest skip") end
end end

