local function toLuaHex(s)
	local t = {string.byte(s, 1, -1)}
	for i = 1, #t do t[i] = string.format('\\x%02X', t[i]) end
	return table.concat(t)
end

local TMP = (gg.EXT_CACHE_DIR or "/sdcard") .. "/Onlyorvex.lua"
local dumps = {
    ["dump"] = function(...)
        io.open(TMP,"w"):write(...) 
     dump = string.dump(loadfile(TMP), true)
     pcall(os.remove, TMP)
     return dump
    end, 
    ["internal"] = function(...)
        local tmp = (gg.EXT_CACHE_DIR or "/sdcard") .. "/Onlyorvex.lasm"
        io.open(TMP,"w"):write(...) 
     dump = string.dump(loadfile(TMP), true)
        io.open(TMP,"w"):write(dump)
        if type(gg.internal2)=="function" then
          pcall(function() gg.internal2(loadfile(TMP), tmp) end)
          local rf = io.open(tmp, "r")
          if rf then
            local d = rf:read("*all")
            rf:close()
            if type(d)=="string" and #d>50 then dump = d end
          end
          pcall(os.remove, tmp)
        end
        pcall(os.remove, TMP)
     return dump
    end
}
